// Tiered triage: each tier tries to settle the alert without calling the model.
// The model is a last resort, reached only by alerts that are genuinely ambiguous.
// See docs/decisions.md.

const sd = $getWorkflowStaticData('global');
const now = Date.now();

const DEDUP_WINDOW_MS = 6 * 60 * 60 * 1000;
const DAILY_WINDOW_MS = 24 * 60 * 60 * 1000;
const MAX_LLM_PER_DAY = 20;
const MIN_INTERVAL_MS = 8000;

const alert = ($input.first().json.body && $input.first().json.body.alert) || {};
const raw = JSON.stringify(alert);

// ---------- indicator extraction ----------
const isPrivateIp = (ip) => {
  const p = ip.split('.').map(Number);
  if (p.length !== 4 || p.some((n) => Number.isNaN(n) || n < 0 || n > 255)) return true;
  return (
    p[0] === 0 || p[0] === 10 || p[0] === 127 ||
    (p[0] === 172 && p[1] >= 16 && p[1] <= 31) ||
    (p[0] === 192 && p[1] === 168) ||
    (p[0] === 169 && p[1] === 254) ||
    p[0] >= 224
  );
};

const allIps = [...new Set(raw.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) || [])];
const publicIps = allIps.filter((ip) => !isPrivateIp(ip));
const hashes = [...new Set([
  ...(raw.match(/\b[a-fA-F0-9]{64}\b/g) || []),
  ...(raw.match(/\b[a-fA-F0-9]{32}\b/g) || []),
])];
const hasActionableIoc = publicIps.length > 0 || hashes.length > 0;

// ---------- alert fingerprint ----------
const ruleId = (alert.rule && alert.rule.id) || 'unknown';
const ruleLevel = Number((alert.rule && alert.rule.level) || 0);
const ruleDesc = (alert.rule && alert.rule.description) || '';
const agentName = (alert.agent && alert.agent.name) || 'unknown';
const fingerprint = [ruleId, agentName, publicIps.slice().sort().join(','), hashes.slice().sort().join(',')].join('|');

// ---------- tier 0: deduplication ----------
if (!sd.verdictCache) sd.verdictCache = {};
for (const k of Object.keys(sd.verdictCache)) {
  if (now - sd.verdictCache[k].at > DEDUP_WINDOW_MS) delete sd.verdictCache[k];
}

const decide = (path, output, detail) => [{
  json: {
    needsLlm: path === 'llm',
    output,
    _triage: {
      path,
      detail,
      fingerprint,
      ruleId,
      ruleLevel,
      agentName,
      publicIps,
      hashes,
      llmCallsToday: (sd.llmCallTimestamps || []).length,
      maxLlmPerDay: MAX_LLM_PER_DAY,
    },
    alert,
  },
}];

const cached = sd.verdictCache[fingerprint];
if (cached) {
  const ageMin = Math.round((now - cached.at) / 60000);
  return decide('cache', cached.output, `cached verdict replayed (seen ${ageMin} min ago)`);
}

// ---------- tier 1: deterministic pre-filter ----------
// With no actionable indicator there is nothing to enrich, and the model would add no information
// the Wazuh rule does not already carry. Escalate for human review instead of spending a call.
if (!hasActionableIoc) {
  const output = {
    severity: ruleLevel >= 12 ? 'high' : 'medium',
    verdict: 'needs_human_review',
    action: 'escalate',
    summary: `Wazuh rule ${ruleId} (level ${ruleLevel}) on ${agentName}: ${ruleDesc}. No external indicator (public IP or file hash) is present in the alert.`,
    reasoning: 'Settled deterministically, without calling the model: with no actionable indicator there is nothing for threat intelligence to enrich, and no reasoning the model could add on top of the rule itself. Escalated for human review, following the escalate-when-in-doubt rule.',
  };
  return decide('deterministic', output, 'no actionable indicator, settled without a model call');
}

// ---------- tier 2: spend guard ----------
if (!sd.llmCallTimestamps) sd.llmCallTimestamps = [];
sd.llmCallTimestamps = sd.llmCallTimestamps.filter((t) => now - t < DAILY_WINDOW_MS);

const last = sd.llmCallTimestamps.length ? sd.llmCallTimestamps[sd.llmCallTimestamps.length - 1] : 0;
const sinceLastMs = now - last;
const underDailyCap = sd.llmCallTimestamps.length < MAX_LLM_PER_DAY;
const spacedEnough = sinceLastMs >= MIN_INTERVAL_MS;

if (!underDailyCap || !spacedEnough) {
  const cause = !underDailyCap
    ? `daily cap of ${MAX_LLM_PER_DAY} calls reached`
    : `calls too close together (${sinceLastMs} ms since the last one, minimum ${MIN_INTERVAL_MS} ms)`;
  const output = {
    severity: ruleLevel >= 12 ? 'high' : 'medium',
    verdict: 'needs_human_review',
    action: 'escalate',
    summary: `Wazuh rule ${ruleId} (level ${ruleLevel}) on ${agentName}: ${ruleDesc}. Automated triage could not run.`,
    reasoning: `Spend guard tripped: ${cause}. The alert is escalated without model analysis rather than being dropped or closed by default.`,
  };
  return decide('rate_limited', output, cause);
}

// ---------- tier 3: hand over to the model ----------
sd.llmCallTimestamps.push(now);
return decide('llm', null, `${publicIps.length} public IP(s), ${hashes.length} hash(es) to enrich`);

// Cache the verdict the model just produced, so the same alert replayed within the dedup window
// is answered without a second call. This is what makes the cascade pay off over time.

const sd = $getWorkflowStaticData('global');
const output = $input.first().json.output;
const triage = $('Triage Cascade').first().json._triage;

if (!sd.verdictCache) sd.verdictCache = {};
sd.verdictCache[triage.fingerprint] = { at: Date.now(), output };

return [{ json: { output, _triage: triage } }];
